import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.BF53ZjCA.js";const u=JSON.parse('{"title":"Same-Colour Gems","description":"","frontmatter":{"title":"Same-Colour Gems","identification":"same-color-gems"},"headers":[],"relativePath":"identification/same-color-gems.md","filePath":"identification/same-color-gems.md","lastUpdated":1790876393000}'),i={name:"identification/same-color-gems.md"};function o(s,e,d,l,c,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="same-colour-gems" tabindex="-1">Same-Colour Gems <a class="header-anchor" href="#same-colour-gems" aria-label="Permalink to &quot;Same-Colour Gems&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>One colour can hide many species — red may be ruby, spinel, garnet, or glass. Combining RI / SG / pleochroism / inclusions narrows the candidate set, but overlap and unresolved results are normal. The red case is expanded alongside minimal blue and green educational branches; none is a complete decision tree for every material.</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-same-color-gems-en"><p class="gem-identification-boundary__eyebrow">IDENTIFICATION BOUNDARY</p><h2 id="identification-boundary-same-color-gems-en">Boundary &amp; Safety</h2><p>Same-colour cases practise the candidate–evidence–next-step loop; they do not name a stone from colour or one RI reading. The red, blue, and green branches are minimal educational cases, not coverage of every material, treatment, or instrument condition. When candidates cannot be excluded or results conflict, stop over-interpreting and refer the sample. </p></aside><h2 id="identification-steps" tabindex="-1">Identification Steps <a class="header-anchor" href="#identification-steps" aria-label="Permalink to &quot;Identification Steps&quot;">​</a></h2><p><strong>Shared reading protocol</strong></p><p>Use the same order for every colour case: fix observation conditions → form candidates → choose suitable low-risk evidence → record support/conflict/unresolved status → decide whether to escalate. Colour raises a question; it does not provide a name.</p><h2 id="_1-blue-candidate-branch" tabindex="-1">1. Blue candidate branch <a class="header-anchor" href="#_1-blue-candidate-branch" aria-label="Permalink to &quot;1. Blue candidate branch&quot;">​</a></h2><p><strong>1. Fix colour and observation conditions</strong></p><p>Record light source, background, mounting, transparency, and cut before recording “blue”. Tanzanite appearance changes with crystal direction, cut orientation, and light; iolite can also show blue-violet, grey-blue, or near-colourless/yellow clues by direction. Record what was seen and under which conditions instead of one colour label.</p><p><strong>2. Form candidates with RI</strong></p><table tabindex="0"><thead><tr><th>Typical reference</th><th>Candidate direction</th><th>Next</th></tr></thead><tbody><tr><td>1.762–1.770</td><td>Corundum / sapphire candidate</td><td>Record birefringence, pleochroism, sample state, and treatment clues</td></tr><tr><td>1.691–1.700</td><td>Tanzanite candidate</td><td>Cross-check directional pleochroism, cut, and treatment context</td></tr><tr><td>About 1.54–1.55</td><td>Iolite candidate</td><td>Record directional colours with a dichroscope; do not bind it to sapphire</td></tr><tr><td>Unstable or inaccessible</td><td>Do not branch yet</td><td>Record unsuitable/unreliable rather than filling the gap from appearance</td></tr></tbody></table><p>These are typical reference ranges, not hard thresholds. Sample state, contact, direction, and instrument conditions can make readings unavailable or different; colour candidates can still overlap.</p><p><strong>3. Use pleochroism to ask the next question</strong></p><table tabindex="0"><thead><tr><th>Observation</th><th>Can support</th><th>Cannot establish</th></tr></thead><tbody><tr><td>Clear directional colour change</td><td>A candidate with directional optical behavior</td><td>Tanzanite or iolite identity alone</td></tr><tr><td>Weak or unobserved change</td><td>An observation under the current setup</td><td>Exclusion of sapphire, tanzanite, or iolite</td></tr><tr><td>Change after lighting changes</td><td>Need to record lighting and colour conditions</td><td>Treatment or origin by itself</td></tr></tbody></table><p><strong>4. Blue escalation conditions</strong></p><p>Stop colour-based inference when RI and pleochroism conflict, mounting/cut makes direction uncontrolled, or heat-treatment, origin, natural/synthetic, or formal disclosure is required. Preserve raw observations and refer to a qualified laboratory.</p><h2 id="_2-green-candidate-branch" tabindex="-1">2. Green candidate branch <a class="header-anchor" href="#_2-green-candidate-branch" aria-label="Permalink to &quot;2. Green candidate branch&quot;">​</a></h2><p><strong>1. Separate colour observation from material identity</strong></p><p>Green may correspond to emerald, tsavorite, peridot, green tourmaline, jadeite, or an imitation. Hue, transparency, and “oily/glassy” appearance form candidates only; they do not exclude materials.</p><p><strong>2. Form candidates with RI/SG</strong></p><table tabindex="0"><thead><tr><th>Typical reference</th><th>Candidate direction</th><th>Next</th></tr></thead><tbody><tr><td>RI 1.577–1.583; SG about 2.72</td><td>Emerald candidate</td><td>Cross-check inclusions, treatment clues, and growth-origin questions</td></tr><tr><td>RI 1.739–1.744; SG about 3.61</td><td>Tsavorite candidate</td><td>Keep separate from other green garnets and colour overlap</td></tr><tr><td>RI about 1.65–1.69; marked birefringence</td><td>Peridot candidate</td><td>Cross-check SG, birefringence, colour, and inclusions</td></tr><tr><td>Unstable or inaccessible</td><td>Do not branch yet</td><td>Record limits; do not use green appearance as evidence</td></tr></tbody></table><p>These are typical references, not automatic naming rules. Green garnets can overlap in colour, and peridot RI/SG can vary with colour and inclusions; preserve conditions instead of choosing the nearest name.</p><p><strong>3. Keep treatment and growth origin separate</strong></p><p>Emerald material identity and oil/filling status are different questions; colour similarity between green garnet and peridot does not make them the same mineral. Treatment, natural/synthetic status, origin, and value must be recorded separately.</p><p><strong>4. Green escalation conditions</strong></p><p>Stop educational branching when oil/filling, natural versus synthetic, jadeite versus another green material, composite structure, or formal transaction disclosure must be established. Also refer conflicting RI, SG, optical, and microscopy results rather than hiding the conflict.</p><h2 id="_3-shared-result-template" tabindex="-1">3. Shared result template <a class="header-anchor" href="#_3-shared-result-template" aria-label="Permalink to &quot;3. Shared result template&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Example</th></tr></thead><tbody><tr><td>Task boundary</td><td>Educational screening / pre-purchase review / formal disclosure</td></tr><tr><td>Sample limits</td><td>Mounted, cabochon, size, fissures, accessible surfaces</td></tr><tr><td>Candidate set</td><td>Sapphire, tanzanite; or emerald, tsavorite, peridot</td></tr><tr><td>Evidence status</td><td>Supports / consistent / cannot exclude / unreliable</td></tr><tr><td>Next step</td><td>Add suitable evidence / preserve conflict / laboratory referral</td></tr></tbody></table><p><strong>Case boundary</strong></p><p>All red, blue, and green paths are minimal educational cases. Do not force them onto mounted, cabochon, fractured, opaque, inaccessible, or valuable specimens. Preserve conditions for every “supports a candidate” result; if results conflict, record the conflict instead of selecting the most intuitive name.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Red case: ruby RI and fluorescence can support a candidate together; spinel, garnet, and glass ranges may overlap with other materials.</li><li>Blue case: sapphire, tanzanite, and iolite RI/pleochroism clues can suggest the next question, but this is not a complete identification tree.</li><li>Green case: emerald, tsavorite, and peridot properties and optical clues can branch candidates, while conditions and overlap must remain explicit.</li><li>Fluorescence is only a screening clue: natural ruby may show strong LW red, but intensity varies with origin, treatment, and sample; synthetics can overlap.</li><li>No single observation replaces laboratory identification; use UV, scratch, and liquid tests only with appropriate equipment and safety procedures.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Value</th><th>Note</th></tr></thead><tbody><tr><td>ruby</td><td>RI 1.76 + red fluor.</td><td>Supports a corundum/ruby candidate; cross-check required</td></tr><tr><td>sapphire</td><td>RI about 1.76; directional pleochroism</td><td>Preserve light and direction when branching against tanzanite or iolite</td></tr><tr><td>tanzanite</td><td>RI 1.691–1.700; pleochroism</td><td>Typical reference; cut and lighting affect appearance</td></tr><tr><td>iolite</td><td>RI about 1.54–1.55; strong pleochroism</td><td>Record colour change by direction; not a standalone ID</td></tr><tr><td>emerald</td><td>RI 1.577–1.583; SG about 2.72</td><td>Record treatment and growth origin separately</td></tr><tr><td>tsavorite-garnet</td><td>RI 1.739–1.744; SG about 3.61</td><td>Green overlap candidate; colour alone cannot name it</td></tr><tr><td>peridot</td><td>RI about 1.65–1.69; marked birefringence</td><td>Typical reference; combine with sample and inclusion context</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/gems-gemology/winter-2024-gemstone-analysis" target="_blank" rel="noreferrer">GIA: Analysis of Gemstones at GIA Laboratories</a><span>Standard gemological testing, laboratory workflow, and laboratory-grown diamond analysis examples</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA: Analytical Methods Used in Geographic Origin Determination</a><span>RI/SG as an identification starting point and further analysis for origin opinions</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2024-infrared-spectroscopy" target="_blank" rel="noreferrer">GIA: Infrared Spectroscopy and Its Use in Gemology</a><span>Spectroscopy and its relationship to atomic structure and natural/synthetic/treatment clues</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/ruby" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Ruby</a><span>Typical ruby RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/sapphire" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Sapphire</a><span>Typical sapphire RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/emerald" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Emerald</a><span>Typical emerald RI, birefringence, specific gravity, hardness, and treatment/synthetic/imitation context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/spinel" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Spinel</a><span>Typical spinel RI, isotropy, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/diamond" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Diamond</a><span>Typical diamond RI, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/zircon" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Zircon</a><span>Typical zircon RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/articles/iolite-description" target="_blank" rel="noreferrer">GIA: Iolite Description</a><span>Iolite pleochroism and viewing-direction context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/tanzanite-description" target="_blank" rel="noreferrer">GIA: Tanzanite Description</a><span>Tanzanite pleochroism, orientation, lighting, and heat-treatment context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/peridot" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Peridot</a><span>Typical peridot RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://my.gia.edu/FAQ/gia-faq-two-green-garnet" target="_blank" rel="noreferrer">GIA FAQ: Tsavorite and Demantoid</a><span>Green garnet colour overlap and mineral distinction context</span><small>Open source ↗</small></li></ul></aside><p><em>See the <a href="./intro.html">identification overview</a>.</em></p>',37)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
